    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    result = deepcopy(grid)

    for r in range(rows):
        row = grid[r]

        # Find adjacent pairs of identical special values (2 or 3)
        i = 0
        while i < cols:
            if row[i] in (2, 3):
                start = i
                # Look for consecutive values
                while i < cols and row[i] == row[start]:
                    i += 1

                length = i - start

                # Determine fill distance
                if row[start] == 2:
                    fill_dist = 10
                else:
                    fill_dist = 8

                # Fill the region after the group
                fill_end = min(i + fill_dist, cols)

                # Fill with 3s, but don't overwrite other special markers
                for c in range(i, fill_end):
                    if c >= cols:
                        break
                    if result[r][c] not in (2, 3):
                        result[r][c] = 3
                i += length
            else:
                i += 1

    return result
